async function handleChargeRefunded(
  charge: StripeChargeShape,
  supabase: SupabaseServiceClient,
): Promise<void> {
  const piId = charge.payment_intent
  if (!piId) {
    logger.warn({ charge_id: charge.id }, 'charge.refunded: missing payment_intent — skipping')
    return
  }

  // Update stripe_charges.status (existing behavior).
  const newStatus = charge.amount_refunded === charge.amount ? 'refunded' : 'partially_refunded'

  const fromUntyped = supabase.from.bind(supabase) as unknown as (table: string) => {
    update: (vals: Record<string, unknown>) => {
      eq: (col: string, val: string) => Promise<{ error: unknown }>
    }
  }
  const { error: updateErr } = await fromUntyped('stripe_charges')
    .update({ status: newStatus })
    .eq('payment_intent_id', piId)
  if (updateErr) {
    logger.error({ pi_id: piId, err: updateErr }, 'charge.refunded: stripe_charges status update failed')
    throw updateErr
  }

  // S19 — mirror each refund in the charge.refunds array to stripe_refunds table.
  const refunds = charge.refunds?.data ?? []
  let resolvedStudioId = charge.metadata?.inkos_studio_id ?? null
  if (!resolvedStudioId) {
    const fromUntypedSelect = supabase.from.bind(supabase) as unknown as (table: string) => {
      select: (cols: string) => {
        eq: (col: string, val: string) => {
          maybeSingle: () => Promise<{
            data: { studio_id: string } | null
            error: unknown
          }>
        }
      }
    }
    const { data: chargeRow } = await fromUntypedSelect('stripe_charges')
      .select('studio_id')
      .eq('payment_intent_id', piId)
      .maybeSingle()
    resolvedStudioId = chargeRow?.studio_id ?? null
  }

  if (!resolvedStudioId) {
    logger.warn({ pi_id: piId, charge_id: charge.id }, 'charge.refunded: studio_id unresolvable — refund mirror skipped')
    return
  }

  for (const refund of refunds) {
    const idempotencyKey = `webhook:charge.refunded:${refund.id}`
    const { error: refundRecErr } = await supabase.rpc(RPC.STRIPE_REFUND_RECORD, {
      p_studio_id: resolvedStudioId,
      p_refund_id: refund.id,
      p_charge_id: charge.id,
      p_payment_intent_id: piId,
      p_amount_cents: refund.amount,
      p_currency: refund.currency,
      p_status: refund.status,
      p_reason: refund.reason ?? null,
      p_initiated_by_user_id: null,
      p_notes: null,
      p_metadata: refund.metadata ?? null,
      p_idempotency_key: idempotencyKey,
    })
    if (refundRecErr) {
      logger.error(
        { pi_id: piId, refund_id: refund.id, err: refundRecErr },
        'S19: stripe_refund_record failed — recoverable via reconciliation',
      )
    }
  }

  logger.info(
    {
      pi_id: piId,
      charge_id: charge.id,
      amount_refunded: charge.amount_refunded,
      refunds_mirrored: refunds.length,
      status: newStatus,
    },
    'charge.refunded webhook processed',
  )
}
```

